"use client";

import { useMemo, useState, type FormEvent, type ReactNode } from "react";
import type { Locale, Messages } from "../../i18n";
import type { Row, Snapshot } from "../../types";
import { ActionButton, NumericStepper, SearchableSelect, TextInput } from "../../components/interface";
import { Inspector, Timeline } from "../../components/interface/workspace";
import { CompareSurface } from "../../components/oic-frames";
import { DeltaIndicator, NodeTrack, NumericInstrument, StateBeacon } from "../../components/instruments";

export type RuntimeModel = { id: string; object?: string; owned_by?: string };
type LabProps = {
  locale: Locale; t: Messages; data: Snapshot | null; profiles: Row[]; executions: Row[];
  workbenchResult: Row | null; selectedTrace: Row | null; traceLoading?: boolean; traceError?: string;
  executionListState?: "loading" | "available" | "failed";
  runtimeResult?: Row | null; onRuntimeResult?: (result: Row) => void;
  runtimeModels: RuntimeModel[]; runtimeModelState: "loading" | "available" | "failed";
  selectRuntimeTenant: (tenantId: string) => void;
  loadExecutions: () => void; inspectTrace: (traceId: string) => Promise<Row | null>;
  runWorkbench: (request: { model: string; profileRevisionId: string; tenantId: string; prompt: string; maxOutputUnits: number }) => Promise<Row | null>;
  runRuntime: (request: { model: string; tenantId: string; prompt: string; maxOutputUnits: number }) => Promise<Row | null>;
  navigate: (destination: "workbench" | "runtime" | "traces" | "memory" | "knowledge" | "profiles" | "models", entityId?: string) => void;
};

const object = (value: unknown): Row => value && typeof value === "object" && !Array.isArray(value) ? value as Row : {};
const list = (value: unknown): Row[] => Array.isArray(value) ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];
const scalar = (value: unknown): string | null => typeof value === "string" || typeof value === "number" || typeof value === "boolean" ? String(value) : null;
const safeCode = (value: unknown) => typeof value === "string" && /^[A-Za-z0-9_.:-]{1,80}$/.test(value) ? value : null;
const technical = (value: unknown) => <bdi dir="ltr" className="lab-technical">{scalar(value) ?? "—"}</bdi>;
const copy = (locale: Locale, en: string, ar: string) => locale === "ar" ? ar : en;

function PageHeading({ index, title, subtitle, state, stateLabel, navigate, locale }: { index: string; title: string; subtitle: string; state: "READY" | "IDLE" | "UNAVAILABLE"; stateLabel: string; navigate: LabProps["navigate"]; locale: Locale }) {
  return <><header className="lab-page-heading"><div><span className="section-index">OIC LAB / {index}</span><h2>{title}</h2><p>{subtitle}</p></div><div className="lab-readiness"><StateBeacon state={state} stateLabel={stateLabel} size="SM"/><small>{copyLabel(index)}</small></div></header><LabRibbon current={index} navigate={navigate} locale={locale} /></>;
}

function copyLabel(index: string) { return index === "01" ? "EXPERIMENT" : index === "02" ? "RUNTIME" : "TRACE"; }

function LabRibbon({ current, navigate, locale }: { current: string; navigate: LabProps["navigate"]; locale: Locale }) {
  const items = [{ index: "01", view: "workbench" as const, en: "Experiment", ar: "التجربة" }, { index: "02", view: "runtime" as const, en: "Runtime", ar: "التشغيل" }, { index: "03", view: "traces" as const, en: "Trace", ar: "الأثر" }];
  return <nav className="lab-ribbon" aria-label={copy(locale, "OIC Lab workflow", "مسار مختبر OIC")}>{items.map((item, i) => <span className="lab-ribbon-item" key={item.index}><span aria-current={current === item.index ? "step" : undefined}><ActionButton variant={current === item.index ? "secondary" : "quiet"} size="compact" className={`lab-ribbon-step${current === item.index ? " is-current" : ""}`} onPress={() => navigate(item.view)}><b>{item.index}</b>{locale === "ar" ? item.ar : item.en}</ActionButton></span>{i < items.length - 1 && <i aria-hidden="true">/</i>}</span>)}</nav>;
}

function Condition({ label, value, detail }: { label: string; value: string; detail?: string }) {
  return <div className="lab-condition"><small>{label}</small><b>{value}</b>{detail && <span>{detail}</span>}</div>;
}

function ReadinessRack({ items, ready, readyLabel, blockedLabel }: { items: { label: string; value: boolean | "unavailable"; detail: string }[]; ready: boolean; readyLabel: string; blockedLabel: string }) {
  return <section className={`lab-readiness-rack${ready ? " is-ready" : " is-blocked"}`} aria-label={ready ? readyLabel : blockedLabel}><header><div><span className="section-index">EXECUTION READINESS</span><h3>{ready ? readyLabel : blockedLabel}</h3></div><StateBeacon state={ready ? "READY" : "IDLE"} stateLabel={ready ? readyLabel : blockedLabel} /></header><div className="lab-readiness-items">{items.map((item) => { const state = item.value === "unavailable" ? "UNAVAILABLE" : item.value ? "READY" : "IDLE"; const label = item.value === "unavailable" ? "UNAVAILABLE" : item.value ? "READY" : "MISSING"; return <div className="lab-readiness-item" key={item.label}><StateBeacon state={state} stateLabel={label} size="SM"/><div><b>{item.label}</b><small>{item.detail}</small></div><span>{label}</span></div>; })}</div></section>;
}

function ExperimentLane({ locale, kind, policy, profile, run, traceAction }: { locale: Locale; kind: "baseline" | "augmented"; policy: string; profile: string; run: Row; traceAction: ReactNode }) {
  const evidence = Object.keys(run).length > 0;
  const execution = object(run.execution);
  const failed = safeCode(execution.status)?.includes("FAIL");
  return <article className={`lab-experiment-lane lab-lane-${kind}${evidence ? " has-evidence" : " is-dormant"}`}><header><div><span className="section-index">{kind === "baseline" ? "A / BASELINE EXECUTION" : "B / OIC EXECUTION"}</span><h4>{kind === "baseline" ? copy(locale, "Baseline execution", "تنفيذ خط الأساس") : copy(locale, "OIC execution", "تنفيذ OIC")}</h4></div><StateBeacon state={failed ? "FAULT" : evidence ? "READY" : "IDLE"} stateLabel={failed ? copy(locale, "FAILED", "فشل") : evidence ? copy(locale, "COMPLETE", "مكتمل") : copy(locale, "READY AFTER RUN", "جاهز بعد التشغيل")} /></header><div className="lab-lane-policy"><small>{kind === "baseline" ? copy(locale, "POLICY", "السياسة") : copy(locale, "PROFILE REVISION", "إصدار الملف")}</small><b>{kind === "baseline" ? policy : profile}</b></div>{evidence ? <RunEvidence locale={locale} run={run} traceAction={traceAction} /> : <div className="lab-lane-dormant"><span>{kind === "baseline" ? copy(locale, "Returned evidence appears after the paired run.", "تظهر الأدلة المعادة بعد تشغيل المقارنة.") : copy(locale, "Selected OIC policy resolves for this execution.", "تُحل سياسة OIC المحددة لهذا التنفيذ.")}</span><small>{copy(locale, "TRACE AVAILABLE AFTER RETURN", "يتاح الأثر بعد الاستجابة")}</small></div>}</article>;
}

function SelectField({ locale, label, value, onChange, options, disabled = false, placeholder }: { locale: Locale; label: string; value: string; onChange: (value: string) => void; options: { id: string; label: string; secondary?: string; scope?: string }[]; disabled?: boolean; placeholder: string }) {
  return <SearchableSelect label={label} value={value} onChange={onChange} options={options} placeholder={placeholder} searchLabel={copy(locale, `Search ${label}`, `بحث ${label}`)} emptyLabel={copy(locale, "No matching options", "لا توجد خيارات مطابقة")} errorLabel={copy(locale, "Options could not be loaded", "تعذر تحميل الخيارات")} locale={locale} dir={locale === "ar" ? "rtl" : "ltr"} disabled={disabled} />;
}

export function WorkbenchWorkspace({ locale, data, profiles, runtimeModels, runtimeModelState, selectRuntimeTenant, workbenchResult, inspectTrace, runWorkbench, navigate }: LabProps) {
  const [model, setModel] = useState("");
  const [profileRevisionId, setProfileRevisionId] = useState("");
  const [tenantId, setTenantId] = useState("");
  const [prompt, setPrompt] = useState("");
  const [maxOutputUnits, setMaxOutputUnits] = useState(1024);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");
  const models = runtimeModels.map((item) => ({ id: item.id, label: item.id, secondary: "Visible Oi runtime identity", scope: item.owned_by ?? "OIC runtime" }));
  const revisions = profiles.filter((profile) => profile.lifecycle === "ACTIVE").flatMap((profile) => list(profile.revisions).map((revision) => ({ id: scalar(revision.id) ?? "", label: `${scalar(profile.profileKey) ?? scalar(profile.displayName) ?? "Profile"} · r${scalar(revision.revision) ?? "?"}`, secondary: scalar(revision.id) ?? "", scope: "Active profile revision" }))).filter((item) => item.id);
  const tenants = (data?.runtimeContext?.tenants ?? []).map((item) => ({ id: scalar(item.id) ?? "", label: scalar(item.displayName) ?? scalar(item.key) ?? "Tenant", secondary: scalar(item.key) ?? "", scope: "Granted runtime tenant" })).filter((item) => item.id);
  const scopeReady = Boolean(tenantId || data?.runtimeContext?.application);
  const ready = Boolean(model && profileRevisionId && scopeReady && prompt.trim() && maxOutputUnits >= 1 && maxOutputUnits <= 8192 && !pending && runtimeModelState === "available");
  const selectedProfile = revisions.find((item) => item.id === profileRevisionId)?.label ?? copy(locale, "No profile revision selected", "لم يُحدد إصدار ملف");
  const selectedScope = tenantId ? tenants.find((item) => item.id === tenantId)?.label ?? copy(locale, "Selected tenant", "المستأجر المحدد") : scalar(data?.runtimeContext?.application?.displayName) ?? copy(locale, "Application scope", "نطاق التطبيق");
  const onSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!ready) return;
    setPending(true); setError("");
    try {
      const body = await runWorkbench({ model, profileRevisionId, tenantId, prompt, maxOutputUnits });
      if (!body) throw new Error(copy(locale, "The comparison could not be completed. Check the OIC response and retry deliberately.", "تعذرت مقارنة التنفيذ. راجع استجابة OIC ثم أعد المحاولة يدويًا."));
    } catch (cause) { setError(cause instanceof Error ? cause.message : copy(locale, "The comparison could not be completed.", "تعذرت مقارنة التنفيذ.")); }
    finally { setPending(false); }
  };
  const run = (key: "baseline" | "augmented") => object(workbenchResult?.[key]);
  const result = (key: "baseline" | "augmented") => run(key);
  const traceButton = (key: "baseline" | "augmented") => {
    const traceId = scalar(result(key).traceId);
    return traceId ? <button className="oi-action is-secondary" type="button" onClick={() => { void inspectTrace(traceId).then((trace) => { if (trace) navigate("traces", traceId); }); }}>{copy(locale, "Inspect trace", "فحص الأثر")} <bdi dir="ltr">↗</bdi></button> : <span className="lab-muted">{copy(locale, "Trace not returned", "لم يُرجع أثر")}</span>;
  };
  return <section className="lab-workspace" dir={locale === "ar" ? "rtl" : "ltr"}>
    <PageHeading index="01" title={copy(locale, "Intelligence Workbench", "منضدة الذكاء")} subtitle={copy(locale, "Design a controlled pair, run both policies, and inspect only returned evidence.", "صمّم مقارنة منضبطة، وشغّل السياستين، وافحص الأدلة المعادة فقط.")} state={runtimeModelState === "failed" ? "UNAVAILABLE" : ready ? "READY" : "IDLE"} stateLabel={runtimeModelState === "failed" ? copy(locale, "UNAVAILABLE", "غير متاح") : ready ? copy(locale, "READY", "جاهز") : copy(locale, "BLOCKED", "متوقف")} locale={locale} navigate={navigate} />
    <section className="lab-experiment-identity"><header><div><span className="section-index">EXPERIMENT / SHARED CONDITIONS</span><h3>{copy(locale, "Held constant across both executions", "ثوابت في كلا التنفيذين")}</h3></div><span className="lab-method-note">{copy(locale, "POLICY DIFFERS", "السياسة تختلف")}</span></header><div className="lab-condition-grid"><Condition label={copy(locale, "Model", "النموذج")} value={model || copy(locale, "Not selected", "غير محدد")} detail={runtimeModelState === "failed" ? copy(locale, "Runtime discovery unavailable", "اكتشاف التشغيل غير متاح") : copy(locale, "Runtime-visible Oi identity", "هوية Oi مرئية للتشغيل")} /><Condition label={copy(locale, "Task", "المهمة")} value={prompt.trim() ? copy(locale, "Shared task input", "مدخل مهمة مشترك") : copy(locale, "Not supplied", "غير مقدم")} detail={copy(locale, "Task text is not stored in the URL or experiment history.", "لا يُخزن نص المهمة في الرابط أو سجل التجارب.")} /><Condition label={copy(locale, "Tenant / application scope", "نطاق المستأجر / التطبيق")} value={selectedScope} detail={tenantId ? copy(locale, "Selected authorized tenant", "المستأجر المصرح به المحدد") : copy(locale, "Console application context", "سياق تطبيق Console")} /><Condition label={copy(locale, "Output ceiling", "حد الإخراج")} value={`${maxOutputUnits.toLocaleString(locale)} ${copy(locale, "tokens", "رمز")}`} detail={copy(locale, "Configured limit · not measured usage", "حد مضبوط · ليس استخدامًا مقاسًا")} /></div><div className="lab-policy-difference"><div><small>{copy(locale, "BASELINE POLICY", "سياسة خط الأساس")}</small><b>FAST</b><span>{copy(locale, "Built-in policy", "سياسة مدمجة")}</span></div><div aria-hidden="true">≠</div><div><small>{copy(locale, "OIC POLICY", "سياسة OIC")}</small><b>{selectedProfile}</b><span>{copy(locale, "Selected immutable profile revision", "إصدار ملف محفوظ غير قابل للتغيير")}</span></div></div></section>
    <section className="lab-experiment-console"><form className="lab-experiment-definition" onSubmit={(event) => { void onSubmit(event); }}>
      <div className="lab-panel-head"><div><span className="section-index">EXPERIMENT INPUT / 01</span><h3>{copy(locale, "Set up the paired run", "إعداد التشغيل المزدوج")}</h3></div><StateBeacon state={ready ? "READY" : runtimeModelState === "failed" ? "UNAVAILABLE" : "IDLE"} stateLabel={ready ? copy(locale, "READY", "جاهز") : runtimeModelState === "failed" ? copy(locale, "UNAVAILABLE", "غير متاح") : copy(locale, "BLOCKED", "متوقف")} /></div>
      <div className="lab-control-grid"><SelectField locale={locale} label={copy(locale, "Oi model", "نموذج Oi")} value={model} onChange={setModel} options={models} disabled={runtimeModelState !== "available"} placeholder={runtimeModelState === "loading" ? copy(locale, "Loading runtime-visible models…", "جارٍ تحميل نماذج التشغيل المرئية…") : copy(locale, "Choose runtime-visible Oi model", "اختر نموذج Oi مرئيًا للتشغيل")} /><SelectField locale={locale} label={copy(locale, "Profile revision", "إصدار الملف")} value={profileRevisionId} onChange={setProfileRevisionId} options={revisions} placeholder={copy(locale, "Choose active revision", "اختر إصدارًا نشطًا")} /><SelectField locale={locale} label={copy(locale, "Tenant scope", "نطاق المستأجر")} value={tenantId} onChange={(value) => { setTenantId(value); setModel(""); selectRuntimeTenant(value); }} options={tenants} placeholder={copy(locale, "Application scope", "نطاق التطبيق")} /><NumericStepper label={copy(locale, "Output ceiling", "حد الإخراج")} value={maxOutputUnits} onChange={setMaxOutputUnits} min={1} max={8192} step={128} unit={copy(locale, "tokens max", "رمز كحد أقصى")} locale={locale} dir={locale === "ar" ? "rtl" : "ltr"} density="compact" /></div>
      <label className="lab-prompt-field"><span>{copy(locale, "Experiment task", "مهمة التجربة")}</span><textarea value={prompt} onChange={(event) => setPrompt(event.currentTarget.value)} maxLength={12000} required aria-describedby="lab-prompt-note" dir={locale === "ar" ? "rtl" : "auto"} placeholder={copy(locale, "Enter the same task for both executions…", "أدخل المهمة نفسها لكلا التنفيذين…")} /><small id="lab-prompt-note">{copy(locale, "Shared across both real executions · not persisted as experiment history", "مشتركة بين تنفيذين فعليين · لا تُحفظ كسجل تجارب")} · {prompt.length}/12000</small></label>
      <div className="lab-run-command"><div><span className="section-index">RUN CONTROL</span><b>{copy(locale, "A paired run makes two real runtime calls.", "تجري المقارنة طلبَي تشغيل حقيقيين.")}</b><small>{copy(locale, "Provider usage may apply; no cost estimate is available.", "قد ينتج عنها استخدام للمزود؛ لا يتوفر تقدير للتكلفة.")}</small></div><ActionButton className="lab-submit" type="submit" variant="primary" disabled={!ready} loading={pending}>{pending ? copy(locale, "EXECUTING", "قيد التنفيذ") : copy(locale, "Run controlled comparison", "تشغيل مقارنة منضبطة")}</ActionButton></div>
      {!ready && <p className="lab-blocked-reason" role="status">{runtimeModelState === "failed" ? copy(locale, "Blocked: runtime model discovery is unavailable.", "متوقف: اكتشاف نماذج التشغيل غير متاح.") : copy(locale, "Blocked until model, profile, scope, task and output ceiling are ready.", "يتوقف حتى يصبح النموذج والملف والنطاق والمهمة وحد الإخراج جاهزين.")}</p>}{error && <p role="alert" className="oi-validation-message is-error">{error}</p>}
    </form><aside className="lab-experiment-readiness"><ReadinessRack ready={ready} readyLabel={copy(locale, "EXPERIMENT READY", "التجربة جاهزة")} blockedLabel={copy(locale, "EXPERIMENT BLOCKED", "التجربة متوقفة")} items={[{ label: copy(locale, "Model", "النموذج"), value: runtimeModelState === "failed" ? "unavailable" : !!model && runtimeModelState === "available", detail: model || copy(locale, "Select a runtime-visible Oi model", "اختر نموذج Oi مرئيًا للتشغيل") }, { label: copy(locale, "Profile", "الملف"), value: !!profileRevisionId, detail: selectedProfile }, { label: copy(locale, "Scope", "النطاق"), value: scopeReady, detail: selectedScope }, { label: copy(locale, "Task", "المهمة"), value: !!prompt.trim(), detail: prompt.trim() ? copy(locale, "Shared input supplied", "تم توفير مدخل مشترك") : copy(locale, "Input required", "المدخل مطلوب") }, { label: copy(locale, "Output", "الإخراج"), value: maxOutputUnits >= 1 && maxOutputUnits <= 8192, detail: `${maxOutputUnits.toLocaleString(locale)} · ${copy(locale, "configured ceiling", "حد مضبوط")}` }]} /></aside></section>
    <section className="lab-experiment-topology"><div className="lab-topology-label"><span className="section-index">EXPERIMENT TOPOLOGY / NOT RUNTIME STAGES</span><small>{copy(locale, "One shared input branches into two policy executions.", "يتفرع مدخل مشترك إلى تنفيذي سياستين.")}</small></div><NodeTrack label={copy(locale, "Experiment structure", "بنية التجربة")} nodes={[{ label: copy(locale, "Shared input", "مدخل مشترك"), value: prompt.trim() ? copy(locale, "SET", "محدد") : copy(locale, "WAIT", "انتظار"), state: prompt.trim() ? "READY" : "IDLE" }, { label: copy(locale, "Paired execution", "تنفيذ مزدوج"), value: workbenchResult ? copy(locale, "RETURNED", "معاد") : copy(locale, "READY AFTER RUN", "بعد التشغيل"), state: workbenchResult ? "READY" : "IDLE" }, { label: copy(locale, "Evidence / trace", "الأدلة / الأثر"), value: workbenchResult ? copy(locale, "AVAILABLE", "متاح") : copy(locale, "AFTER RUN", "بعد التشغيل"), state: workbenchResult ? "READY" : "IDLE" }]} />
      <CompareSurface title={copy(locale, "Paired execution lanes", "مسارا التنفيذ المزدوج")} compareLabel={copy(locale, "HELD CONDITIONS · DIFFERENT POLICIES", "ثوابت المقارنة · سياسات مختلفة")} sides={[<ExperimentLane key="baseline" locale={locale} kind="baseline" policy={copy(locale, "FAST · built-in baseline", "FAST · خط أساس مدمج")} profile="" run={result("baseline")} traceAction={traceButton("baseline")} />, <ExperimentLane key="oic" locale={locale} kind="augmented" policy="" profile={selectedProfile} run={result("augmented")} traceAction={traceButton("augmented")} />]}>
        <div className="lab-delta-strip"><div><span className="section-index">OBSERVED DELTAS</span><b>{copy(locale, "Measured differences only", "الفروق المقاسة فقط")}</b></div>{workbenchResult ? <>{[[copy(locale, "Duration", "المدة"), run("augmented").durationMs, run("baseline").durationMs, " ms"], [copy(locale, "Provider calls", "استدعاءات المزود"), object(run("augmented").execution).providerCallCount, object(run("baseline").execution).providerCallCount, ""], [copy(locale, "Retrieval queries", "استعلامات الاسترجاع"), object(run("augmented").execution).retrievalQueryCount, object(run("baseline").execution).retrievalQueryCount, ""], [copy(locale, "Output tokens", "رموز الإخراج"), object(run("augmented").usage).outputTokens, object(run("baseline").usage).outputTokens, ""]].map(([label, current, previous, unit]) => <div className="lab-delta-value" key={String(label)}><small>{String(label)}</small><DeltaIndicator current={typeof current === "number" ? current : undefined} previous={typeof previous === "number" ? previous : undefined} unit={String(unit)} /></div>)}</> : <p>{copy(locale, "Values appear only when both executions return comparable measurements. Direction is not a quality judgment.", "تظهر القيم عند إعادة قياسات قابلة للمقارنة من التنفيذين فقط. الاتجاه ليس حكم جودة.")}</p>}</div>
      </CompareSurface>
      <div className="lab-method-footer"><span>{copy(locale, "No score or winner", "لا توجد نتيجة تقييم أو فائز")}</span><p>{copy(locale, "Only actual returned measurements are compared. The effective contexts differ because the OIC lane resolves the selected profile and its configured behavior.", "تُقارن القياسات الفعلية المعادة فقط. تختلف السياقات الفعلية لأن مسار OIC يحل الملف المحدد وسلوكياته المضبوطة.")}</p><ActionButton variant="quiet" size="compact" onPress={() => navigate("runtime")}>{copy(locale, "Open Runtime Lab", "فتح مختبر التشغيل")} ↗</ActionButton></div>
    </section>
  </section>;
}

function RunEvidence({ locale, run, traceAction }: { locale: Locale; run: Row; traceAction: ReactNode }) {
  const execution = object(run.execution); const usage = object(run.usage);
  const fields: [string, unknown][] = [
    [copy(locale, "Outcome", "النتيجة"), run.finishReason], [copy(locale, "Duration", "المدة"), typeof run.durationMs === "number" ? `${run.durationMs} ms` : null],
    [copy(locale, "Provider calls", "استدعاءات المزود"), execution.providerCallCount], [copy(locale, "Retrieval queries", "استعلامات الاسترجاع"), execution.retrievalQueryCount],
    [copy(locale, "Memory lookups", "عمليات بحث الذاكرة"), execution.memoryLookupCount], [copy(locale, "Verification", "التحقق"), execution.verificationStatus],
    [copy(locale, "Input / output tokens", "رموز الإدخال / الإخراج"), usage.inputTokens != null || usage.outputTokens != null ? `${scalar(usage.inputTokens) ?? "—"} / ${scalar(usage.outputTokens) ?? "—"}` : null]
  ];
  return <div className="lab-run-evidence"><StateBeacon state={safeCode(execution.status) === "FAILED" ? "FAULT" : "LIVE"} stateLabel={scalar(execution.status) ?? copy(locale, "Response received", "تم استلام الاستجابة")} /><p className="lab-run-output">{scalar(run.outputText) ?? copy(locale, "No output text was returned.", "لم يُرجع نص إخراج.")}</p><div className="lab-evidence-grid">{fields.map(([label, value]) => <div key={label}><small>{label}</small><b>{scalar(value) ?? copy(locale, "Not recorded", "غير مسجل")}</b></div>)}</div><div className="lab-run-actions">{traceAction}<span>{copy(locale, "Request", "الطلب")} {technical(run.requestId)}</span></div></div>;
}

export function RuntimeWorkspace({ locale, data, runtimeModels, runtimeModelState, runtimeResult, onRuntimeResult, selectRuntimeTenant, runRuntime, inspectTrace, navigate }: LabProps) {
  const [model, setModel] = useState(""); const [tenantId, setTenantId] = useState(""); const [prompt, setPrompt] = useState(""); const [maxOutputUnits, setMaxOutputUnits] = useState(1024);
  const [pending, setPending] = useState(false); const [error, setError] = useState("");
  const tenants = (data?.runtimeContext?.tenants ?? []).map((item) => ({ id: scalar(item.id) ?? "", label: scalar(item.displayName) ?? scalar(item.key) ?? "Tenant", secondary: scalar(item.key) ?? "", scope: "Granted runtime tenant" })).filter((item) => item.id);
  const modelOptions = runtimeModels.map((item) => ({ id: item.id, label: item.id, secondary: "Oi runtime identity", scope: item.owned_by ?? "OIC" }));
  const selectedScope = tenantId ? tenants.find((item) => item.id === tenantId)?.label ?? copy(locale, "Selected tenant", "المستأجر المحدد") : scalar(data?.runtimeContext?.application?.displayName) ?? copy(locale, "Application scope", "نطاق التطبيق");
  const scopeReady = Boolean(tenantId || data?.runtimeContext?.application);
  const runtimeAvailable = runtimeModelState === "available" && runtimeModels.length > 0;
  const runnable = !!model && scopeReady && !!prompt.trim() && !pending && runtimeAvailable;
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!runnable) return; setPending(true); setError(""); try { const response = await runRuntime({ model, tenantId, prompt, maxOutputUnits }); if (!response) throw new Error(copy(locale, "No invocation response was received.", "لم يتم استلام استجابة تنفيذ.")); onRuntimeResult?.(response); } catch (cause) { setError(cause instanceof Error ? cause.message : copy(locale, "Invocation failed.", "فشل التنفيذ.")); } finally { setPending(false); } };
  const runtime = object(runtimeResult?.result ?? runtimeResult); const output = list(runtime.output).flatMap((item) => list(item.content)).map((item) => scalar(item.text)).filter(Boolean).join("\n");
  const runtimeErrorCode = safeCode(object(runtime.error).code) ?? safeCode(runtime.code) ?? safeCode(runtime.error);
  const usage = object(runtime.usage); const traceId = scalar(runtimeResult?.traceId ?? runtime.traceId); const reqId = scalar(runtimeResult?.requestId ?? runtime.requestId);
  const knownModelCount = runtimeModels.length;
  return <section className="lab-workspace" dir={locale === "ar" ? "rtl" : "ltr"}>
    <PageHeading index="02" title={copy(locale, "Runtime Lab", "مختبر التشغيل")} subtitle={copy(locale, "Resolve an Oi runtime identity, make one bounded invocation, then inspect its returned response and trace.", "حل هوية تشغيل Oi، ونفّذ طلبًا محدودًا، ثم افحص الاستجابة والأثر المعادين.")} state={runtimeModelState === "failed" || runtimeModelState === "available" && knownModelCount === 0 ? "UNAVAILABLE" : runnable ? "READY" : "IDLE"} stateLabel={runtimeModelState === "failed" || runtimeModelState === "available" && knownModelCount === 0 ? copy(locale, "UNAVAILABLE", "غير متاح") : runnable ? copy(locale, "READY", "جاهز") : copy(locale, "BLOCKED", "متوقف")} locale={locale} navigate={navigate} />
    <section className="lab-runtime-identity"><div><small>{copy(locale, "RUNTIME MODEL", "نموذج التشغيل")}</small><b>{model || copy(locale, "Not selected", "غير محدد")}</b></div><div><small>{copy(locale, "APPLICATION", "التطبيق")}</small><b>{scalar(data?.runtimeContext?.application?.displayName) ?? copy(locale, "Context unavailable", "السياق غير متاح")}</b></div><div><small>{copy(locale, "TENANT", "المستأجر")}</small><b>{tenantId ? tenants.find((item) => item.id === tenantId)?.label ?? copy(locale, "Selected", "محدد") : copy(locale, "Application scope", "نطاق التطبيق")}</b></div><div><small>{copy(locale, "RESOLVED PROFILE", "الملف المحلول")}</small><b>{copy(locale, "Determined by model binding", "يحدده ربط النموذج")}</b></div><div><small>{copy(locale, "RUNTIME AVAILABILITY", "توفر التشغيل")}</small><b>{runtimeModelState === "failed" ? copy(locale, "UNAVAILABLE", "غير متاح") : runtimeModelState === "loading" ? copy(locale, "CHECKING", "جارٍ الفحص") : knownModelCount ? copy(locale, `${knownModelCount} visible models`, `${knownModelCount} نماذج مرئية`) : copy(locale, "NO VISIBLE MODELS", "لا توجد نماذج مرئية")}</b></div></section>
    <section className="lab-runtime-topology"><div className="lab-topology-label"><span className="section-index">RUNTIME FLOW / SERVICE BOUNDARIES</span><small>{copy(locale, "High-level request path; internal stages are not represented here.", "مسار طلب عالي المستوى؛ لا تمثل المراحل الداخلية هنا.")}</small></div><NodeTrack label={copy(locale, "Runtime request and response flow", "مسار طلب واستجابة التشغيل")} nodes={[{ label: copy(locale, "Model resolution", "حل النموذج"), value: model || copy(locale, "WAIT", "انتظار"), state: model ? "READY" : runtimeModelState === "failed" ? "UNAVAILABLE" : "IDLE" }, { label: copy(locale, "Request", "الطلب"), value: prompt.trim() ? copy(locale, "READY", "جاهز") : copy(locale, "INPUT", "مدخل"), state: prompt.trim() ? "READY" : "IDLE" }, { label: copy(locale, "OIC runtime", "تشغيل OIC"), value: runtimeResult ? copy(locale, "RETURNED", "معاد") : copy(locale, "READY AFTER RUN", "بعد التشغيل"), state: runtimeResult ? Number(runtimeResult.httpStatus) >= 500 ? "FAULT" : "READY" : "IDLE" }, { label: copy(locale, "Response", "الاستجابة"), value: runtimeResult ? copy(locale, Number(runtimeResult.httpStatus) >= 400 ? "FAILED" : "RETURNED", Number(runtimeResult.httpStatus) >= 400 ? "فشل" : "معاد") : copy(locale, "AFTER RUN", "بعد التشغيل"), state: runtimeResult ? Number(runtimeResult.httpStatus) >= 400 ? "FAULT" : "READY" : "IDLE" }, { label: copy(locale, "Trace", "الأثر"), value: traceId ? copy(locale, "AVAILABLE", "متاح") : copy(locale, "AFTER RUN", "بعد التشغيل"), state: traceId ? "READY" : "IDLE" }]} /></section>
    <div className="lab-runtime-layout"><form className="lab-panel lab-runtime-builder" onSubmit={(event) => { void submit(event); }}>
      <div className="lab-panel-head"><div><span className="section-index">REQUEST BUILDER / 02</span><h3>{copy(locale, "Configure invocation", "ضبط طلب التشغيل")}</h3></div><StateBeacon state={pending ? "LIVE" : runnable ? "READY" : runtimeModelState === "failed" ? "UNAVAILABLE" : "IDLE"} stateLabel={pending ? copy(locale, "EXECUTING", "قيد التنفيذ") : runnable ? copy(locale, "READY", "جاهز") : runtimeModelState === "failed" ? copy(locale, "UNAVAILABLE", "غير متاح") : copy(locale, "BLOCKED", "متوقف")} /></div>
      <div className="lab-control-grid"><SelectField locale={locale} label={copy(locale, "Runtime model", "نموذج التشغيل")} value={model} onChange={setModel} options={modelOptions} placeholder={runtimeModelState === "loading" ? copy(locale, "Loading visible models…", "جارٍ تحميل النماذج المرئية…") : copy(locale, "Choose visible Oi model", "اختر نموذج Oi مرئيًا")} disabled={runtimeModelState !== "available"} /><SelectField locale={locale} label={copy(locale, "Tenant scope", "نطاق المستأجر")} value={tenantId} onChange={(value) => { setTenantId(value); setModel(""); selectRuntimeTenant(value); }} options={tenants} placeholder={copy(locale, "Application scope", "نطاق التطبيق")} /><NumericStepper label={copy(locale, "Output ceiling", "حد الإخراج")} value={maxOutputUnits} onChange={setMaxOutputUnits} min={1} max={65536} step={256} unit={copy(locale, "tokens max", "رمز كحد أقصى")} locale={locale} dir={locale === "ar" ? "rtl" : "ltr"} density="compact" /></div>
      <label className="lab-prompt-field"><span>{copy(locale, "Request input", "مدخل الطلب")}</span><textarea value={prompt} onChange={(event) => setPrompt(event.currentTarget.value)} maxLength={12000} required dir={locale === "ar" ? "rtl" : "auto"} placeholder={copy(locale, "Enter the text sent to the selected Oi model…", "أدخل النص المرسل إلى نموذج Oi المحدد…")} /><small>{copy(locale, "Sent to the real runtime service · the resolved profile is determined by its binding", "يُرسل إلى خدمة التشغيل الفعلية · يحدد ربط النموذج الملف المحلول")} · {prompt.length}/12000</small></label>
      <div className="lab-runtime-scope"><span>{copy(locale, "Scope", "النطاق")}</span><b>{selectedScope}</b><small>{copy(locale, "Only API-visible Oi identities are selectable.", "يمكن اختيار هويات Oi المرئية من API فقط.")}</small></div>
      <div className="lab-run-command"><div><span className="section-index">INVOCATION COMMAND</span><b>{copy(locale, "One request · real OIC runtime", "طلب واحد · تشغيل OIC فعلي")}</b><small>{copy(locale, "Provider usage may apply; no cost estimate is available.", "قد ينتج عنها استخدام للمزود؛ لا يتوفر تقدير للتكلفة.")}</small></div><ActionButton type="submit" variant="primary" disabled={!runnable} loading={pending}>{pending ? copy(locale, "EXECUTING", "قيد التنفيذ") : copy(locale, "Run invocation", "تشغيل الطلب")}</ActionButton></div>
      <ReadinessRack ready={runnable} readyLabel={copy(locale, "INVOCATION READY", "التنفيذ جاهز")} blockedLabel={copy(locale, "INVOCATION BLOCKED", "التنفيذ متوقف")} items={[{ label: copy(locale, "Model", "النموذج"), value: runtimeModelState === "failed" ? "unavailable" : !!model && runtimeModelState === "available", detail: model || copy(locale, "Select a runtime-visible model", "اختر نموذجًا مرئيًا للتشغيل") }, { label: copy(locale, "Scope", "النطاق"), value: scopeReady, detail: selectedScope }, { label: copy(locale, "Input", "المدخل"), value: !!prompt.trim(), detail: prompt.trim() ? copy(locale, "Request input supplied", "تم توفير مدخل الطلب") : copy(locale, "Input required", "المدخل مطلوب") }, { label: copy(locale, "Runtime", "التشغيل"), value: runtimeModelState === "failed" ? "unavailable" : runtimeAvailable, detail: runtimeModelState === "failed" ? copy(locale, "Discovery unavailable", "الاكتشاف غير متاح") : `${knownModelCount} ${copy(locale, "visible model identities", "هويات نماذج مرئية")}` }]} />
      {!runnable && <p className="lab-blocked-reason" role="status">{runtimeModelState === "failed" || runtimeModelState === "available" && knownModelCount === 0 ? copy(locale, "Precondition blocked: no runtime-visible model is available.", "توقف شرط مسبق: لا يتوفر نموذج مرئي للتشغيل.") : copy(locale, "Precondition blocked until model, scope and request input are ready.", "توقف شرط مسبق حتى يصبح النموذج والنطاق ومدخل الطلب جاهزين.")}</p>}{error && <p role="alert" className="oi-validation-message is-error">{error}</p>}
      <div className="lab-cross-actions"><ActionButton variant="quiet" size="compact" onPress={() => navigate("workbench")}>{copy(locale, "Open Workbench", "فتح منضدة العمل")} ↗</ActionButton><ActionButton variant="quiet" size="compact" onPress={() => navigate("traces")}>{copy(locale, "Open Execution Traces", "فتح آثار التنفيذ")} ↗</ActionButton></div>
    </form><section className="lab-panel lab-runtime-observation" aria-live="polite"><div className="lab-panel-head"><div><span className="section-index">OBSERVATION / 03</span><h3>{copy(locale, "Response and evidence", "الاستجابة والأدلة")}</h3></div><StateBeacon state={runtimeResult ? Number(runtimeResult.httpStatus) >= 500 ? "FAULT" : Number(runtimeResult.httpStatus) >= 400 ? "DEGRADED" : "READY" : runtimeModelState === "failed" ? "UNAVAILABLE" : "IDLE"} stateLabel={runtimeResult ? Number(runtimeResult.httpStatus) >= 400 ? copy(locale, "FAILED", "فشل") : copy(locale, "COMPLETE", "مكتمل") : runtimeModelState === "failed" ? copy(locale, "PRECONDITION UNAVAILABLE", "شرط مسبق غير متاح") : copy(locale, "READY FOR INVOCATION", "جاهز للتنفيذ")} /></div>
      {runtimeResult ? <><div className="lab-correlation"><span>{copy(locale, "Request", "الطلب")} {technical(reqId)}</span><span>{copy(locale, "Trace", "الأثر")} {traceId ? technical(traceId) : copy(locale, "Not returned", "لم يُرجع")}</span><span>{copy(locale, "Duration", "المدة")} <b>{scalar(runtime.execution && object(runtime.execution).durationMs) ?? copy(locale, "Not recorded", "غير مسجل")} ms</b></span></div>{Number(runtimeResult.httpStatus) >= 400 && <div className="lab-invocation-failure" role="alert"><StateBeacon state={Number(runtimeResult.httpStatus) >= 500 ? "FAULT" : "DEGRADED"} stateLabel={copy(locale, Number(runtimeResult.httpStatus) >= 500 ? "RUNTIME FAILURE" : "REQUEST FAILURE", Number(runtimeResult.httpStatus) >= 500 ? "فشل التشغيل" : "فشل الطلب")} /><div><h4>{copy(locale, "Invocation returned an error", "أعاد التنفيذ خطأ")}</h4><p>{copy(locale, "Safe API code", "رمز API آمن")}: {runtimeErrorCode ?? copy(locale, "Not returned", "لم يُرجع")}</p></div></div>}<article className="lab-response"><h4>{copy(locale, "Actual runtime response", "استجابة التشغيل الفعلية")}</h4><pre>{output || copy(locale, "No output text was returned.", "لم يُرجع نص إخراج.")}</pre><small>{copy(locale, "Finish reason", "سبب الإنهاء")}: {safeCode(runtime.finish_reason ?? runtime.finishReason) ?? copy(locale, "Not recorded", "غير مسجل")}</small></article><div className="lab-usage-rack"><div><NumericInstrument label={copy(locale, "Input tokens · returned", "رموز الإدخال · معادة")} value={typeof usage.prompt_tokens === "number" ? usage.prompt_tokens : typeof usage.inputTokens === "number" ? usage.inputTokens : null} state={typeof usage.prompt_tokens === "number" || typeof usage.inputTokens === "number" ? "READY" : "UNMEASURED"} source="Runtime response" /></div><div><NumericInstrument label={copy(locale, "Output used · returned", "الإخراج المستخدم · معاد")} value={typeof usage.completion_tokens === "number" ? usage.completion_tokens : typeof usage.outputTokens === "number" ? usage.outputTokens : null} state={typeof usage.completion_tokens === "number" || typeof usage.outputTokens === "number" ? "READY" : "UNMEASURED"} source="Runtime response" /></div><div><NumericInstrument label={copy(locale, "Output ceiling · configured", "حد الإخراج · مضبوط")} value={maxOutputUnits} state="READY" source="Request configuration" /></div></div><div className="lab-run-actions">{traceId && <ActionButton variant="secondary" onPress={() => { void inspectTrace(traceId).then((trace) => { if (trace) navigate("traces", traceId); }); }}>{copy(locale, "Open execution trace", "فتح أثر التنفيذ")} ↗</ActionButton>}<ActionButton variant="quiet" disabled={!runnable} onPress={() => { void submit(new Event("submit") as unknown as FormEvent); }}>{copy(locale, "Retry as new invocation", "إعادة كطلب جديد")}</ActionButton></div></> : <div className={`lab-runtime-empty${runtimeModelState === "failed" ? " is-unavailable" : ""}`}><div><span className="section-index">{runtimeModelState === "failed" ? "PRECONDITION / MODEL DISCOVERY" : "RESPONSE SURFACE / DORMANT"}</span><h4>{runtimeModelState === "failed" ? copy(locale, "Runtime model discovery unavailable", "اكتشاف نماذج التشغيل غير متاح") : copy(locale, "Ready for invocation", "جاهز للتنفيذ")}</h4><p>{runtimeModelState === "failed" ? copy(locale, "The runtime model list could not be loaded; no invocation was attempted.", "تعذر تحميل قائمة نماذج التشغيل؛ لم يُجرَ أي تنفيذ.") : copy(locale, "A real response, returned measurements and trace correlation appear here after an authorized invocation.", "تظهر هنا الاستجابة الفعلية والقياسات المعادة وارتباط الأثر بعد تنفيذ مصرح به.")}</p></div><div className="lab-response-anatomy">{[copy(locale, "Execution status", "حالة التنفيذ"), copy(locale, "Response", "الاستجابة"), copy(locale, "Evidence", "الأدلة"), copy(locale, "Trace", "الأثر")].map((item, i) => <span key={item}><b>0{i + 1}</b>{item}<small>{copy(locale, "AFTER INVOCATION", "بعد التنفيذ")}</small></span>)}</div></div>}
    </section></div>
  </section>;
}

const SAFE_SUMMARY_NUMBERS = ["candidateCount", "toolCalls", "revisions", "verificationPasses", "cacheHits", "cacheMisses"] as const;
function safeSummary(summary: Row) {
  const counts = SAFE_SUMMARY_NUMBERS.flatMap((key) => typeof summary[key] === "number" && Number.isFinite(summary[key]) ? [[key, summary[key]] as const] : []);
  const stopReason = safeCode(summary.stopReason);
  return { counts, stopReason };
}
function safeResource(resource: Row) {
  const allowed = ["providerCalls", "retrievalQueries", "memoryLookups", "contextTokens", "inputTokens", "outputTokens", "toolCalls"] as const;
  return allowed.flatMap((key) => typeof resource[key] === "number" && Number.isFinite(resource[key]) ? [[key, resource[key]] as const] : []);
}
function safeStageEvents(trace: Row, locale: Locale) {
  return list(trace.stages).map((stage, index) => {
    const state = safeCode(stage.status) ?? "UNKNOWN";
    return { id: `${scalar(stage.stageIndex) ?? index}-${scalar(stage.stageType) ?? "stage"}`, title: `${copy(locale, "Stage", "المرحلة")} ${scalar(stage.stageIndex) ?? index + 1} · ${safeCode(stage.stageType) ?? copy(locale, "Unclassified", "غير مصنف")}`, detail: [safeCode(stage.strategy), `${scalar(stage.durationMs) ?? "—"} ms`, state].filter(Boolean).join(" · "), time: scalar(stage.startedAt) ?? undefined, tone: state.includes("FAIL") ? "critical" as const : state.includes("PARTIAL") || state.includes("WARN") ? "warning" as const : state.includes("SUCC") || state.includes("COMPLET") ? "good" as const : "neutral" as const };
  });
}
function traceDuration(startedAt: unknown, completedAt: unknown, locale: Locale) {
  const start = scalar(startedAt); const end = scalar(completedAt);
  if (!start || !end) return copy(locale, "Not recorded", "غير مسجل");
  const duration = Date.parse(end) - Date.parse(start);
  return Number.isFinite(duration) ? `${Math.max(0, duration)} ms` : copy(locale, "Not recorded", "غير مسجل");
}

function shortTraceId(value: unknown) {
  const id = scalar(value);
  if (!id) return null;
  const tail = id.split("-").at(-1) ?? id;
  return tail.slice(0, 8);
}

export function TracesWorkspace({ locale, executions, executionListState = "available", selectedTrace, traceLoading = false, traceError = "", loadExecutions, inspectTrace, navigate }: LabProps) {
  const [query, setQuery] = useState(""); const [inspectorOpen, setInspectorOpen] = useState(false); const [copiedTraceId, setCopiedTraceId] = useState(false);
  const visible = useMemo(() => { const needle = query.trim().toLocaleLowerCase(locale === "ar" ? "ar" : "en"); if (!needle) return executions; return executions.filter((item) => [item.traceId, item.requestId, item.modelId, item.taskType, item.strategy, item.status].some((value) => scalar(value)?.toLocaleLowerCase(locale === "ar" ? "ar" : "en").includes(needle))); }, [executions, query, locale]);
  const summary = safeSummary(object(selectedTrace?.summary)); const stages = selectedTrace ? safeStageEvents(selectedTrace, locale) : [];
  const stageList = list(selectedTrace?.stages);
  const status = safeCode(selectedTrace?.status) ?? "UNKNOWN";
  const tone = status.includes("FAIL") ? "critical" : status.includes("PARTIAL") ? "warning" : status.includes("SUCC") || status.includes("COMPLET") ? "good" : "neutral";
  const returnedCounts = executions.reduce<{ success: number; failed: number; partial: number }>((counts, item) => { const value = safeCode(item.status) ?? "UNKNOWN"; if (value.includes("FAIL")) counts.failed += 1; else if (value.includes("PARTIAL")) counts.partial += 1; else if (value.includes("SUCC") || value.includes("COMPLET")) counts.success += 1; return counts; }, { success: 0, failed: 0, partial: 0 });
  const copyTraceId = async () => { const id = scalar(selectedTrace?.traceId); if (!id) return; try { await navigator.clipboard.writeText(id); setCopiedTraceId(true); window.setTimeout(() => setCopiedTraceId(false), 1400); } catch { setCopiedTraceId(false); } };
  const field = (label: string, value: unknown) => <div className="lab-detail-field" key={label}><small>{label}</small><b>{scalar(value) ?? copy(locale, "Not recorded", "غير مسجل")}</b></div>;
  const traceInspector = selectedTrace ? <div className="lab-safe-inspector"><div className="lab-detail-grid">{field(copy(locale, "Execution ID", "معرّف التنفيذ"), selectedTrace.id)}{field(copy(locale, "Trace ID", "معرّف الأثر"), selectedTrace.traceId)}{field(copy(locale, "Request ID", "معرّف الطلب"), selectedTrace.requestId)}{field(copy(locale, "Model", "النموذج"), selectedTrace.modelId)}{field(copy(locale, "Model revision", "إصدار النموذج"), selectedTrace.modelRevisionId)}{field(copy(locale, "Profile revision", "إصدار الملف"), selectedTrace.profileRevisionId)}{field(copy(locale, "Tenant", "المستأجر"), selectedTrace.tenantId)}{field(copy(locale, "Status", "الحالة"), safeCode(selectedTrace.status))}{field(copy(locale, "Strategy", "الاستراتيجية"), safeCode(selectedTrace.strategy))}{field(copy(locale, "Task type", "نوع المهمة"), safeCode(selectedTrace.taskType))}{field(copy(locale, "Uncertainty", "عدم اليقين"), safeCode(selectedTrace.uncertainty))}{field(copy(locale, "Verification", "التحقق"), safeCode(selectedTrace.verificationStatus))}{field(copy(locale, "Started", "بدأ"), selectedTrace.startedAt)}{field(copy(locale, "Completed", "اكتمل"), selectedTrace.completedAt)}</div><h4>{copy(locale, "Recorded resources", "الموارد المسجلة")}</h4><div className="lab-detail-grid">{field(copy(locale, "Provider calls", "استدعاءات المزود"), selectedTrace.providerCallCount)}{field(copy(locale, "Retrieval queries", "استعلامات الاسترجاع"), selectedTrace.retrievalQueryCount)}{field(copy(locale, "Memory lookups", "عمليات بحث الذاكرة"), selectedTrace.memoryLookupCount)}{field(copy(locale, "Context tokens", "رموز السياق"), selectedTrace.contextTokens)}{field(copy(locale, "Input tokens", "رموز الإدخال"), selectedTrace.inputTokens)}{field(copy(locale, "Output tokens", "رموز الإخراج"), selectedTrace.outputTokens)}{...summary.counts.map(([key, value]) => field(key, value))}{field(copy(locale, "Stop code", "رمز التوقف"), summary.stopReason)}</div><h4>{copy(locale, "Stage evidence", "أدلة المراحل")}</h4><ol className="lab-stage-evidence">{stageList.length ? stageList.map((stage, index) => { const resources = safeResource(object(stage.resourceUse)); return <li key={`${scalar(stage.stageIndex) ?? index}-${scalar(stage.stageType) ?? "stage"}`}><div><b>{scalar(stage.stageIndex) ?? index + 1}. {safeCode(stage.stageType) ?? copy(locale, "Unclassified stage", "مرحلة غير مصنفة")}</b><span>{safeCode(stage.status) ?? "UNKNOWN"} · {safeCode(stage.strategy) ?? copy(locale, "Strategy not recorded", "الاستراتيجية غير مسجلة")} · {scalar(stage.durationMs) ?? "—"} ms</span></div>{resources.length ? <div className="lab-resource-list">{resources.map(([key, value]) => <span key={key}>{key}: {value}</span>)}</div> : <small>{copy(locale, "Stage resource details not recorded", "تفاصيل موارد المرحلة غير مسجلة")}</small>}</li>; }) : <li>{copy(locale, "No stage records returned.", "لم تُرجع سجلات مراحل.")}</li>}</ol><p className="lab-safety-note">{copy(locale, "Only allowlisted identifiers, enums, counts and timestamps are shown. Prompt, response content, raw summary/metadata, provider payloads and private deliberation are excluded.", "تُعرض المعرفات والقيم والتعدادات والتوقيتات المسموح بها فقط. يُستبعد نص الطلب والاستجابة والملخص والبيانات الوصفية الخام وبيانات المزود والمداولات الخاصة.")}</p></div> : null;
  return <section className="lab-workspace" dir={locale === "ar" ? "rtl" : "ltr"}>
    <PageHeading index="03" title={copy(locale, "Execution Traces", "آثار التنفيذ")} subtitle={copy(locale, "Inspect returned execution identity, ordered stages and bounded resource evidence.", "افحص هوية التنفيذ المعادة ومراحلها وأدلة الموارد المحدودة.")} state={executionListState === "failed" ? "UNAVAILABLE" : executionListState === "available" ? "READY" : "IDLE"} stateLabel={executionListState === "failed" ? copy(locale, "UNAVAILABLE", "غير متاح") : executionListState === "loading" ? copy(locale, "LOADING SAMPLE", "تحميل العينة") : copy(locale, "SAMPLE READY", "العينة جاهزة")} locale={locale} navigate={navigate} />
    <section className="lab-trace-summary-rack" aria-label={copy(locale, "Returned trace sample summary", "ملخص عينة الآثار المعادة")}><div><small>{copy(locale, "RETURNED SAMPLE", "العينة المعادة")}</small><b>{executionListState === "failed" ? "—" : executions.length}</b><span>{copy(locale, "newest first · bounded", "الأحدث أولًا · محدودة")}</span></div><div><small>{copy(locale, "SUCCESS", "ناجح")}</small><b>{executionListState === "failed" ? "—" : returnedCounts.success}</b></div><div><small>{copy(locale, "FAILED", "فاشل")}</small><b>{executionListState === "failed" ? "—" : returnedCounts.failed}</b></div><div><small>{copy(locale, "PARTIAL", "جزئي")}</small><b>{executionListState === "failed" ? "—" : returnedCounts.partial}</b></div></section>
    <div className="lab-trace-toolbar"><TextInput label={copy(locale, "Search returned sample", "البحث في العينة المعادة")} value={query} onChange={setQuery} type="search" dir={locale === "ar" ? "rtl" : "ltr"} description={copy(locale, "Searches the current returned sample only · newest first", "يبحث في العينة المعادة الحالية فقط · الأحدث أولًا")} /><ActionButton variant="quiet" size="compact" onPress={loadExecutions}>{copy(locale, "Refresh sample", "تحديث العينة")} ↻</ActionButton></div>
    <div className="lab-trace-layout"><section className="lab-panel lab-trace-index"><div className="lab-panel-head"><div><span className="section-index">TRACE INDEX / NEWEST FIRST</span><h3>{copy(locale, "Returned sample", "العينة المعادة")}</h3></div><small>{copy(locale, "Newest bounded sample", "أحدث عينة محدودة")}</small></div><div className="lab-trace-list" role="list" aria-label={copy(locale, "Execution traces", "آثار التنفيذ")}>{visible.map((item) => <div role="listitem" key={scalar(item.traceId) ?? "trace"}><button type="button" className={`lab-trace-row${selectedTrace?.traceId === item.traceId ? " is-selected" : ""}`} onClick={() => { const traceId = scalar(item.traceId); if (traceId) void inspectTrace(traceId).then((trace) => { if (trace) navigate("traces", traceId); }); }} aria-pressed={selectedTrace?.traceId === item.traceId}><span className="lab-trace-state"><StateBeacon state={safeCode(item.status)?.includes("FAIL") ? "FAULT" : safeCode(item.status)?.includes("PARTIAL") ? "DEGRADED" : safeCode(item.status)?.includes("SUCC") || safeCode(item.status)?.includes("COMPLET") ? "READY" : "IDLE"} stateLabel={safeCode(item.status) ?? "UNKNOWN"} /></span><span className="lab-trace-main"><b>{safeCode(item.status) ?? copy(locale, "UNKNOWN", "غير معروف")} · {technical(item.modelId)}</b><small>{copy(locale, "Profile", "الملف")} {technical(item.profileRevisionId)} · {technical(item.startedAt)}</small><small>{copy(locale, "Duration", "المدة")} {traceDuration(item.startedAt, item.completedAt, locale)} · {copy(locale, "ID", "المعرف")} {technical(shortTraceId(item.traceId))}</small></span><span className="lab-trace-counts">{scalar(item.stageCount) ?? "—"} {copy(locale, "stages", "مراحل")}<small>{scalar(item.providerCallCount) ?? "—"} {copy(locale, "calls", "استدعاءات")}</small></span></button></div>)}{visible.length === 0 && <div className="lab-empty-state"><h4>{executionListState === "failed" ? copy(locale, "Trace sample unavailable", "عينة الآثار غير متاحة") : executionListState === "loading" ? copy(locale, "Loading trace sample…", "جارٍ تحميل عينة الآثار…") : executions.length ? copy(locale, "No matches in this sample", "لا توجد نتائج في هذه العينة") : copy(locale, "No execution records returned", "لم تُرجع سجلات تنفيذ")}</h4><p>{executionListState === "failed" ? copy(locale, "The API did not return a usable trace sample. Refresh after confirming Console/API readiness.", "لم يُرجع API عينة آثار صالحة. حدّث بعد التحقق من جاهزية Console وAPI.") : executionListState === "loading" ? copy(locale, "Fetching the authorized, bounded execution sample.", "جارٍ جلب عينة التنفيذ المحدودة والمصرح بها.") : copy(locale, "An empty response is distinct from a failed trace request. Refresh to query the bounded API sample again.", "الاستجابة الفارغة تختلف عن فشل طلب الأثر. حدّث للاستعلام عن عينة API المحدودة مجددًا.")}</p>{executionListState === "available" && executions.length === 0 && <div className="lab-empty-actions"><ActionButton variant="secondary" size="compact" onPress={() => navigate("workbench")}>{copy(locale, "Open Workbench", "فتح منضدة العمل")} ↗</ActionButton><ActionButton variant="quiet" size="compact" onPress={() => navigate("runtime")}>{copy(locale, "Open Runtime Lab", "فتح مختبر التشغيل")} ↗</ActionButton></div>}</div>}</div><p className="lab-safety-note">{copy(locale, "This list is the newest bounded sample returned by the API, not full trace history. Search, pagination, export and deletion are not available.", "هذه أحدث عينة محدودة أعادها API وليست سجل الآثار الكامل. البحث الشامل والترقيم والتصدير والحذف غير متاحة.")}</p></section>
      <section className="lab-panel lab-trace-inspection" aria-live="polite"><div className="lab-panel-head"><div><span className="section-index">TRACE FORENSICS / EVIDENCE</span><h3>{selectedTrace ? scalar(selectedTrace.modelId) ?? copy(locale, "Selected execution", "التنفيذ المحدد") : copy(locale, "No trace selected", "لم يُحدد أثر")}</h3>{selectedTrace && <small className="lab-selected-trace-id">{copy(locale, "TRACE ID", "معرف الأثر")} {technical(selectedTrace.traceId)}</small>}</div>{selectedTrace && <div className="lab-selected-actions"><ActionButton variant="quiet" size="compact" onPress={() => { void copyTraceId(); }}>{copiedTraceId ? copy(locale, "Copied", "تم النسخ") : copy(locale, "Copy trace ID", "نسخ معرف الأثر")}</ActionButton><ActionButton variant="secondary" size="compact" onPress={() => setInspectorOpen(true)}>{copy(locale, "Inspector", "الفاحص")} ↗</ActionButton></div>}</div>
        {traceLoading ? <div role="status" className="lab-awaiting"><h4>{copy(locale, "Loading trace detail…", "جارٍ تحميل تفاصيل الأثر…")}</h4></div> : traceError ? <div role="alert" className="lab-empty-state"><h4>{copy(locale, "Trace detail unavailable", "تفاصيل الأثر غير متاحة")}</h4><p>{traceError}</p></div> : selectedTrace ? <><div className="lab-selected-identity"><Condition label={copy(locale, "Model", "النموذج")} value={scalar(selectedTrace.modelId) ?? "?"}/><Condition label={copy(locale, "Profile revision", "إصدار الملف")} value={scalar(selectedTrace.profileRevisionId) ?? copy(locale, "Not recorded", "غير مسجل")}/><Condition label={copy(locale, "Started", "بدأ")} value={scalar(selectedTrace.startedAt) ?? copy(locale, "Not recorded", "غير مسجل")}/></div><div className="lab-trace-summary"><div><small>{copy(locale, "STATUS", "الحالة")}</small><b className={`is-${tone}`}>{safeCode(selectedTrace.status) ?? "UNKNOWN"}</b></div><div><small>{copy(locale, "VERIFICATION", "التحقق")}</small><b>{safeCode(selectedTrace.verificationStatus) ?? copy(locale, "Not recorded", "غير مسجل")}</b></div><div><small>{copy(locale, "STAGES", "المراحل")}</small><b>{scalar(selectedTrace.stageCount) ?? stageList.length}</b></div><div><small>{copy(locale, "DURATION", "المدة")}</small><b>{traceDuration(selectedTrace.startedAt, selectedTrace.completedAt, locale)}</b></div></div><Timeline label={copy(locale, "Ordered execution stages", "مراحل التنفيذ المرتبة")} events={stages} /><div className="lab-evidence-rails">{[[copy(locale, "Provider calls", "استدعاءات المزود"), selectedTrace.providerCallCount], [copy(locale, "Retrieval queries", "استعلامات الاسترجاع"), selectedTrace.retrievalQueryCount], [copy(locale, "Memory lookups", "عمليات بحث الذاكرة"), selectedTrace.memoryLookupCount]].map(([label, value]) => <div key={String(label)}><NumericInstrument label={String(label)} value={typeof value === "number" ? value : null} state={typeof value === "number" ? "READY" : "UNMEASURED"} source="Returned trace" /></div>)}</div><p className="lab-safety-note">{copy(locale, "Provider-call and retrieval detail rows are not returned by this API contract; these are aggregate counts only.", "لا يعيد عقد API صفوف تفاصيل استدعاء المزود أو الاسترجاع؛ المعروض تعداد إجمالي فقط.")}</p></>  : <div className="lab-trace-no-selection"><div className="lab-no-selection-copy"><span className="lab-awaiting-mark">OIC / TRACE</span><h4>{executionListState === "failed" ? copy(locale, "Trace list unavailable", "قائمة الآثار غير متاحة") : executionListState === "loading" ? copy(locale, "Loading trace sample?", "جارٍ تحميل عينة الآثار") : copy(locale, "No trace selected", "لم يُحدد أثر")}</h4><p>{executionListState === "failed" ? copy(locale, "The trace source did not return a usable list. Refresh after confirming Console/API readiness.", "لم يُعد مصدر الآثار قائمة صالحة. حدّث بعد التحقق من جاهزية Console وAPI.") : executionListState === "loading" ? copy(locale, "Fetching the authorized, bounded execution sample.", "جارٍ جلب عينة التنفيذ المحدودة والمصرح بها") : copy(locale, "Select a returned execution to inspect its identity, stages and resource evidence.", "اختر تنفيذًا معادًا لفحص هويته ومراحله وأدلة موارده.")}</p></div><div className="lab-trace-anatomy"><div><span className="section-index">TRACE ANATOMY / ON SELECTION</span><small>{copy(locale, "Available evidence depends on the returned trace DTO.", "تعتمد الأدلة المتاحة على بيانات الأثر المعادة.")}</small></div><NodeTrack size="SM" label={copy(locale, "Trace evidence anatomy", "بنية أدلة الأثر")} nodes={[{ label: copy(locale, "Identity", "الهوية"), value: copy(locale, "ON SELECT", "عند الاختيار"), state: "IDLE" }, { label: copy(locale, "Stages", "المراحل"), value: copy(locale, "ON SELECT", "عند الاختيار"), state: "IDLE" }, { label: copy(locale, "Resource counts", "تعداد الموارد"), value: copy(locale, "IF RETURNED", "إن أُعيدت"), state: "IDLE" }, { label: copy(locale, "Verification / response", "التحقق / الاستجابة"), value: copy(locale, "IF RETURNED", "إن أُعيدت"), state: "IDLE" }]}/></div><div className="lab-empty-actions"><ActionButton variant="secondary" size="compact" onPress={() => navigate("workbench")}>{copy(locale, "Open Workbench", "فتح منضدة العمل")} &rarr;</ActionButton><ActionButton variant="quiet" size="compact" onPress={() => navigate("runtime")}>{copy(locale, "Open Runtime Lab", "فتح مختبر التشغيل")} &rarr;</ActionButton></div></div>}
      </section></div>
    {selectedTrace && <Inspector open={inspectorOpen} onClose={() => setInspectorOpen(false)} title={copy(locale, "Safe trace inspector", "فاحص الأثر الآمن")} description={copy(locale, "Allowlisted structured evidence only", "الأدلة المنظمة المسموح بها فقط")} closeLabel={copy(locale, "Close inspector", "إغلاق الفاحص")} dir={locale === "ar" ? "rtl" : "ltr"}>{traceInspector}</Inspector>}
  </section>;
}
